from collections import deque
# equivalence graph: transpose, horizontal reflection around row boundary 15.5 (rows 2..29)
N=30
adj={ (r,c):set() for r in range(N) for c in range(N)}
for r in range(N):
 for c in range(N):
  adj[r,c].add((c,r))
  if 2<=r<=29: adj[r,c].add((31-r,c))
# determine each masked coordinate from any unmasked same component
seen=set(); comps=[]
for p in adj:
 if p in seen: continue
 q=[p];seen.add(p); comp=[]
 while q:
  x=q.pop();comp.append(x)
  for y in adj[x]:
   if y not in seen: seen.add(y);q.append(y)
 comps.append(comp)
for comp in comps:
 vals={g[r][c] for r,c in comp if g[r][c]!=6}
 if len(vals)>1: print('conflict',vals,comp[:10])
 if vals:
  v=next(iter(vals))
  for r,c in comp:
   if g[r][c]==6: g[r][c]=v
print('\n'.join(' '.join(map(str,r)) for r in g))
